import{_ as t,o as a,c as r,a3 as s}from"./chunks/framework.DDSBsJZG.js";const u=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"docs/roadmap.md","filePath":"docs/roadmap.md"}'),n={name:"docs/roadmap.md"};function o(i,e,h,d,l,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>What ships and in which order. A <strong>phase</strong> is a layer of the product (<a href="./architecture#delivery-phases">architecture</a>); a <strong>release</strong> is a set of features inside a phase that makes sense together, cut when it is ready, not on a date.</p><blockquote><p><strong>Draft.</strong> The grouping below awaits the maintainer&#39;s approval in <a href="https://github.com/tkint/coach-poulpy/issues/229" target="_blank" rel="noreferrer">#229</a>. Release numbers after the current one are not final, and the GitHub milestones still follow the phases until it is decided. The current version is the latest tag on the <a href="https://github.com/tkint/coach-poulpy/releases" target="_blank" rel="noreferrer">Releases</a> page.</p></blockquote><p>A GitHub release plus the server deployed on Infomaniak is production (<a href="./releasing">Releasing</a>). Publishing in the app stores comes in its own phase, at the end.</p><h2 id="what-v1-includes" tabindex="-1">What v1 includes <a class="header-anchor" href="#what-v1-includes" aria-label="Permalink to &quot;What v1 includes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>v1</th><th>Later</th><th>Phase</th></tr></thead><tbody><tr><td>Audience</td><td>The family, as guests or with an account</td><td>A public app</td><td>1</td></tr><tr><td>Accounts</td><td>Guest mode with all data on the phone; email and password, with the guest&#39;s data joining the account on sign-up</td><td>Sign in with Apple and Google (<a href="https://github.com/tkint/coach-poulpy/issues/536" target="_blank" rel="noreferrer">#536</a>)</td><td>1, 3</td></tr><tr><td>Website</td><td>Needs an account; plans, manages, reviews and runs guided sessions without devices</td><td></td><td>4</td></tr><tr><td>Catalog</td><td>Curated, published from the server and downloaded by the phone, with simple images; no user-created exercises</td><td>User-created exercises with duplicate detection</td><td>3</td></tr><tr><td>Workouts</td><td>Circuit or sets, in parts (warm-up, work, cool down); strength, cardio, rehab, stretching and treadmill walks and runs</td><td>Outdoor running, walking, swimming with GPS; workout tags</td><td>1</td></tr><tr><td>Treadmill</td><td>FTMS read and record, alone or checked against a planned workout</td><td>Speed and incline control per phase</td><td>2</td></tr><tr><td>Progression</td><td>Every week written out by hand</td><td>Rules from recognised protocols, driven by sessions and goals</td><td>1</td></tr><tr><td>Sharing</td><td>Save to library synced with the author or as a copy</td><td></td><td>5</td></tr><tr><td>Coaching</td><td>Athlete invites a coach and can revoke; coach edits assigned plans and comments on sessions</td><td></td><td>5</td></tr><tr><td>Export</td><td>.FIT file for Garmin Connect and Strava; optional Apple Health and Health Connect</td><td>Direct Garmin and Strava links</td><td>1</td></tr><tr><td>Language and units</td><td>French and English, metric and imperial: distances, speeds and weights follow the setting (weights are stored in kilograms and shown in pounds in imperial), except a distance picked in whole miles or kilometres, which keeps the unit it was picked in</td><td></td><td>1</td></tr><tr><td>Hosting</td><td>A GitHub release for the app and the server on Infomaniak, deployed with Docker to one server (<a href="./adr/0019-the-server-runs-with-docker-compose-on-one-server">ADR 0019</a>): this is production</td><td>A bigger machine or a managed database when it runs short</td><td>3</td></tr><tr><td>Distribution</td><td>A GitHub release with the Android APK; iPhone builds from Xcode</td><td>App Store, TestFlight and Google Play</td><td>6</td></tr></tbody></table><h2 id="phase-1-·-guest-app" tabindex="-1">Phase 1 · Guest app <a class="header-anchor" href="#phase-1-·-guest-app" aria-label="Permalink to &quot;Phase 1 · Guest app&quot;">​</a></h2><p>Everything the app does for one person, on the phone. Accounts and sync already ship (phase 3), so phase 1 is done when the guest features below are complete on both platforms: <strong>1.0</strong>. Releases 0.6 to 0.10 are out; their contents are in the release notes.</p><table tabindex="0"><thead><tr><th>Release</th><th>Theme</th><th>Issues</th></tr></thead><tbody><tr><td>0.11</td><td>Home, Library, You</td><td>The three-tab bar, the diary Home and Record sheet, the You page, empty states, the Home date picker, <a href="https://github.com/tkint/coach-poulpy/issues/523" target="_blank" rel="noreferrer">#523</a> Achievements</td></tr><tr><td>0.12</td><td>Reuse workouts</td><td><a href="https://github.com/tkint/coach-poulpy/issues/37" target="_blank" rel="noreferrer">#37</a> swap an exercise for a variation in the builder, <a href="https://github.com/tkint/coach-poulpy/issues/224" target="_blank" rel="noreferrer">#224</a> a workout from any recorded session, <a href="https://github.com/tkint/coach-poulpy/issues/511" target="_blank" rel="noreferrer">#511</a> search and filters on the diary</td></tr><tr><td>0.13</td><td>Training plans</td><td><a href="https://github.com/tkint/coach-poulpy/issues/17" target="_blank" rel="noreferrer">#17</a> follow a plan, split into tickets first</td></tr><tr><td>0.14</td><td>Beyond the app</td><td><a href="https://github.com/tkint/coach-poulpy/issues/23" target="_blank" rel="noreferrer">#23</a> Apple Health and Health Connect</td></tr><tr><td>1.0</td><td>Phase 1 complete</td><td>Whatever remains in the milestone</td></tr></tbody></table><p>Swapping an exercise during a session (<a href="https://github.com/tkint/coach-poulpy/issues/38" target="_blank" rel="noreferrer">#38</a>) is not planned.</p><h2 id="phase-2-·-treadmill" tabindex="-1">Phase 2 · Treadmill <a class="header-anchor" href="#phase-2-·-treadmill" aria-label="Permalink to &quot;Phase 2 · Treadmill&quot;">​</a></h2><p>Runs alongside phase 1, because the treadmill link was the riskiest piece. What is left is <a href="https://github.com/tkint/coach-poulpy/issues/14" target="_blank" rel="noreferrer">#14</a>, choosing what a device measures from its page, which needs a new design first. Releases are cut with the phase 1 release they fall in.</p><h2 id="phase-3-·-accounts-and-sync" tabindex="-1">Phase 3 · Accounts and sync <a class="header-anchor" href="#phase-3-·-accounts-and-sync" aria-label="Permalink to &quot;Phase 3 · Accounts and sync&quot;">​</a></h2><p>Accounts, sync between phones, catalog updates on launch, the admin gate and the account screens ship. What is left:</p><table tabindex="0"><thead><tr><th>Theme</th><th>Issues</th></tr></thead><tbody><tr><td>Admin catalog workspace</td><td><a href="https://github.com/tkint/coach-poulpy/issues/26" target="_blank" rel="noreferrer">#26</a> and its open child <a href="https://github.com/tkint/coach-poulpy/issues/338" target="_blank" rel="noreferrer">#338</a> (drafts, review and publication by revision)</td></tr><tr><td>Admin</td><td><a href="https://github.com/tkint/coach-poulpy/issues/381" target="_blank" rel="noreferrer">#381</a> a super admin from environment variables</td></tr><tr><td>Sign-in</td><td><a href="https://github.com/tkint/coach-poulpy/issues/536" target="_blank" rel="noreferrer">#536</a> Sign in with Apple and Google</td></tr><tr><td>Calendar feed</td><td><a href="https://github.com/tkint/coach-poulpy/issues/241" target="_blank" rel="noreferrer">#241</a> training days as a calendar other services subscribe to</td></tr></tbody></table><h2 id="phase-4-·-website" tabindex="-1">Phase 4 · Website <a class="header-anchor" href="#phase-4-·-website" aria-label="Permalink to &quot;Phase 4 · Website&quot;">​</a></h2><p><a href="https://github.com/tkint/coach-poulpy/issues/29" target="_blank" rel="noreferrer">#29</a> run the shared engine in the browser with Kotlin/JS, then plan, review and run guided sessions.</p><h2 id="phase-5-·-sharing-and-coaching" tabindex="-1">Phase 5 · Sharing and coaching <a class="header-anchor" href="#phase-5-·-sharing-and-coaching" aria-label="Permalink to &quot;Phase 5 · Sharing and coaching&quot;">​</a></h2><p>Library sync or copy, coach links and comments. Not broken into issues yet.</p><h2 id="phase-6-·-stores" tabindex="-1">Phase 6 · Stores <a class="header-anchor" href="#phase-6-·-stores" aria-label="Permalink to &quot;Phase 6 · Stores&quot;">​</a></h2><p>Publishing beyond GitHub releases: <a href="https://github.com/tkint/coach-poulpy/issues/24" target="_blank" rel="noreferrer">#24</a> the Apple Developer membership and TestFlight, then the App Store and Google Play. Until then iPhone builds come from Xcode.</p><h2 id="later" tabindex="-1">Later <a class="header-anchor" href="#later" aria-label="Permalink to &quot;Later&quot;">​</a></h2><p>Wanted, not planned: <a href="https://github.com/tkint/coach-poulpy/issues/225" target="_blank" rel="noreferrer">#225</a> rethink the workout player and the live recorder as one idea (ADR 0018 stays in force until then), <a href="https://github.com/tkint/coach-poulpy/issues/30" target="_blank" rel="noreferrer">#30</a> control the treadmill, <a href="https://github.com/tkint/coach-poulpy/issues/31" target="_blank" rel="noreferrer">#31</a> heart rate straps, <a href="https://github.com/tkint/coach-poulpy/issues/32" target="_blank" rel="noreferrer">#32</a> user-created exercises, <a href="https://github.com/tkint/coach-poulpy/issues/33" target="_blank" rel="noreferrer">#33</a> progression rules, <a href="https://github.com/tkint/coach-poulpy/issues/75" target="_blank" rel="noreferrer">#75</a> guided building of a long run, <a href="https://github.com/tkint/coach-poulpy/issues/124" target="_blank" rel="noreferrer">#124</a> Poulpy&#39;s coaching style, <a href="https://github.com/tkint/coach-poulpy/issues/228" target="_blank" rel="noreferrer">#228</a> APIs and an MCP server, <a href="https://github.com/tkint/coach-poulpy/issues/481" target="_blank" rel="noreferrer">#481</a> direct Garmin BLE telemetry.</p><h2 id="not-tied-to-a-release" tabindex="-1">Not tied to a release <a class="header-anchor" href="#not-tied-to-a-release" aria-label="Permalink to &quot;Not tied to a release&quot;">​</a></h2><p>Documentation work (<a href="https://github.com/tkint/coach-poulpy/issues/226" target="_blank" rel="noreferrer">#226</a> diagrams, <a href="https://github.com/tkint/coach-poulpy/issues/227" target="_blank" rel="noreferrer">#227</a> readability) and <a href="https://github.com/tkint/coach-poulpy/issues/229" target="_blank" rel="noreferrer">#229</a>, which defines how releases are planned, go in whichever release is open.</p>',25)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
